import{_ as e,o as a,c as d,ah as o}from"./chunks/framework.DjU4PSOm.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"tags":["computer/project"],"date":"2026-10-28T00:00:00.000Z"},"headers":[{"level":3,"title":"오늘 한 것 (2026-10-28)","slug":"오늘-한-것-2026-10-28","link":"#오늘-한-것-2026-10-28","children":[]},{"level":3,"title":"1. 교환일기 화면","slug":"_1-교환일기-화면","link":"#_1-교환일기-화면","children":[]},{"level":3,"title":"2. 1단계 반응","slug":"_2-1단계-반응","link":"#_2-1단계-반응","children":[]},{"level":3,"title":"3. 이번엔 정책을 아예 안 만들었다","slug":"_3-이번엔-정책을-아예-안-만들었다","link":"#_3-이번엔-정책을-아예-안-만들었다","children":[]},{"level":3,"title":"4. 우회 시도 결과","slug":"_4-우회-시도-결과","link":"#_4-우회-시도-결과","children":[]},{"level":3,"title":"5. 네비게이션 구조 변경","slug":"_5-네비게이션-구조-변경","link":"#_5-네비게이션-구조-변경","children":[]},{"level":3,"title":"6. 다음: Android 앱","slug":"_6-다음-android-앱","link":"#_6-다음-android-앱","children":[]},{"level":3,"title":"7. 남은 과제","slug":"_7-남은-과제","link":"#_7-남은-과제","children":[]}],"relativePath":"computer/project/Zing/10. 교환일기 화면과 1단계 반응 (2026-10-28).md","filePath":"computer/project/Zing/10. 교환일기 화면과 1단계 반응 (2026-10-28).md"}'),l={name:"computer/project/Zing/10. 교환일기 화면과 1단계 반응 (2026-10-28).md"};function r(i,t,n,s,c,u){return a(),d("div",null,[...t[0]||(t[0]=[o(`<h3 id="오늘-한-것-2026-10-28" tabindex="-1">오늘 한 것 (2026-10-28) <a class="header-anchor" href="#오늘-한-것-2026-10-28" aria-label="Permalink to &quot;오늘 한 것 (2026-10-28)&quot;">​</a></h3><p>징으로 매칭은 되는데, 매칭된 다음에 할 수 있는 게 없었다. 그래서 <strong>매칭 상대와의 교환일기 화면</strong>과 단계적 소통의 첫 단계인 <strong>1단계 반응(이모지)</strong> 을 만들었다.</p><table tabindex="0"><thead><tr><th>순서</th><th>작업</th><th>상태</th></tr></thead><tbody><tr><td>1</td><td><code>diary_reactions</code> 테이블 + DB 함수 (<code>sql/2026-10-28_reactions.sql</code>)</td><td>완료, 실행 완료</td></tr><tr><td>2</td><td>네비게이션을 &quot;탭 위에 스택&quot; 구조로 변경</td><td>완료</td></tr><tr><td>3</td><td>교환일기 화면 (<code>PartnerScreen</code>)</td><td>완료</td></tr><tr><td>4</td><td>브라우저 검증 + API 직접 호출로 우회 시도</td><td>완료, push 완료</td></tr></tbody></table><hr><h3 id="_1-교환일기-화면" tabindex="-1">1. 교환일기 화면 <a class="header-anchor" href="#_1-교환일기-화면" aria-label="Permalink to &quot;1. 교환일기 화면&quot;">​</a></h3><p>매칭 탭에서 상대를 누르면 &quot;OO님과의 교환일기&quot;로 이동한다.</p><ul><li>나와 상대의 일기를 <strong>한 목록에 최신순으로</strong> 섞어서 보여줌. 교환일기 앱이니까 &quot;주고받은 일기장&quot;처럼 보이게 하려는 것. 내 일기는 회색 배경으로 구분.</li><li>위에 현재 단계와 <strong>다음 단계까지 진행도</strong>: <code>다음 단계까지 (매칭 후 일기) 나 0/2 · 상대 0/2</code>. 단계 기준이 &quot;매칭 후 <strong>둘 다</strong> 쓴 일기 수&quot;라서, 둘의 개수를 같이 보여주면 상대가 안 쓰고 있다는 것도 자연스럽게 보인다.</li><li>진행도는 화면에서 계산한 <strong>표시용</strong>이고, 실제 단계 판정은 DB <code>match_stage</code>가 한다. 기준값(2/4/7)은 <code>lib/constants.ts</code>의 <code>STAGE_THRESHOLDS</code>에 두고 DB와 맞춰야 한다고 주석을 달아둠.</li></ul><h3 id="_2-1단계-반응" tabindex="-1">2. 1단계 반응 <a class="header-anchor" href="#_2-1단계-반응" aria-label="Permalink to &quot;2. 1단계 반응&quot;">​</a></h3><ul><li>상대 일기 아래에 이모지 5개(❤️ 😂 😮 😢 👏). 하나 누르면 선택, 다른 걸 누르면 교체, <strong>같은 걸 다시 누르면 취소</strong>.</li><li>일기 하나에 한 사람당 반응 1개 → PK를 <code>(diary_id, user_id)</code>로 잡아서 DB가 보장. 교체는 <code>on conflict do update</code>.</li><li>내 일기 아래에는 &quot;OO님의 반응 👏&quot; 또는 &quot;아직 반응이 없어요&quot;.</li></ul><h3 id="_3-이번엔-정책을-아예-안-만들었다" tabindex="-1">3. 이번엔 정책을 아예 안 만들었다 <a class="header-anchor" href="#_3-이번엔-정책을-아예-안-만들었다" aria-label="Permalink to &quot;3. 이번엔 정책을 아예 안 만들었다&quot;">​</a></h3><p><code>zings</code>는 SELECT 정책만 있었는데, <code>diary_reactions</code>는 <strong>RLS만 켜고 정책이 0개</strong>다. 정책이 없으면 클라이언트는 아무것도 못 읽고 못 쓴다. 대신:</p><ul><li><code>get_match_diaries(partner)</code> — 매칭 확인 후 양쪽 일기 + 반응을 한 번에 돌려줌</li><li><code>react_to_diary(diary, emoji)</code> — 매칭 상대 일기인지, 내 일기가 아닌지 확인 후 저장</li></ul><p>읽기도 함수로만 하면 &quot;매칭된 두 사람만 서로의 반응을 본다&quot;는 규칙을 정책 SQL로 복잡하게 쓸 필요가 없다. 조회와 권한 확인이 한 함수에 있어서 읽기도 쉬움.</p><h3 id="_4-우회-시도-결과" tabindex="-1">4. 우회 시도 결과 <a class="header-anchor" href="#_4-우회-시도-결과" aria-label="Permalink to &quot;4. 우회 시도 결과&quot;">​</a></h3><p>앱 화면이 아니라 Supabase API를 직접 호출해서 규칙을 깨보려고 했다. 전부 막힘.</p><table tabindex="0"><thead><tr><th>시도</th><th>결과</th></tr></thead><tbody><tr><td>내 일기에 반응</td><td>&quot;내 일기에는 반응할 수 없어요.&quot;</td></tr><tr><td>매칭 안 된 사람 일기에 반응</td><td>&quot;매칭된 상대의 일기에만 반응할 수 있어요.&quot;</td></tr><tr><td>정해진 5개 외 이모지</td><td>check 제약 위반</td></tr><tr><td>매칭 안 된 사람 교환일기 조회</td><td>&quot;매칭된 상대의 일기만 볼 수 있어요.&quot;</td></tr><tr><td>반응 테이블 직접 조회</td><td>빈 배열 (정책 없음)</td></tr><tr><td>내부 함수 <code>is_matched</code> 호출</td><td>permission denied</td></tr></tbody></table><p>화면 검증: UI테스트 계정으로 B의 일기에 ❤️ → 😂 → 취소 → 👏, B 계정으로 로그인하면 자기 일기 아래 &quot;UI테스트님의 반응 👏&quot;.</p><h3 id="_5-네비게이션-구조-변경" tabindex="-1">5. 네비게이션 구조 변경 <a class="header-anchor" href="#_5-네비게이션-구조-변경" aria-label="Permalink to &quot;5. 네비게이션 구조 변경&quot;">​</a></h3><p>교환일기는 탭 안이 아니라 <strong>탭 위에 쌓이는 스택 화면</strong>으로 넣었다.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MainNavigator (스택)</span></span>
<span class="line"><span> ├─ Tabs     (홈 / 일기 쓰기 / 매칭)</span></span>
<span class="line"><span> └─ Partner  (교환일기)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>상세 화면에서는 하단 탭이 사라지고 뒤로가기가 생긴다. 앞으로 채팅도 같은 자리에 추가하면 됨.</p><hr><h3 id="_6-다음-android-앱" tabindex="-1">6. 다음: Android 앱 <a class="header-anchor" href="#_6-다음-android-앱" aria-label="Permalink to &quot;6. 다음: Android 앱&quot;">​</a></h3><p>Expo라서 앱을 따로 만드는 게 아니라 <strong>같은 코드를 폰에서 실행하고 다른 부분만 고치는</strong> 방식. 화면이 6개로 늘어난 지금이 확인하기 좋은 시점이라고 판단.</p><ol><li>Expo Go로 실제 Android 폰에서 실행 (PC와 같은 와이파이, <code>exp://&lt;PC IP&gt;:8081</code>)</li><li>폰에서 깨지는 부분 수정 — 예상: 상단 상태바에 화면 가림, 일기 쓸 때 키보드가 입력창 가림, 버튼 모양 차이</li><li>EAS Build로 설치 파일 만들어 팀원 폰에 설치</li><li>스토어 출시는 런칭 직전 (Google Play 개발자 계정 1회 $25)</li></ol><h3 id="_7-남은-과제" tabindex="-1">7. 남은 과제 <a class="header-anchor" href="#_7-남은-과제" aria-label="Permalink to &quot;7. 남은 과제&quot;">​</a></h3><ul><li>2단계(앱이 주는 오늘의 질문, 5자 답변)부터 미구현</li><li>피드의 매칭 카드에서 바로 교환일기로 가는 링크 없음 (지금은 &quot;매칭 탭에서 볼 수 있어요&quot; 안내만)</li><li>9번 노트의 남은 과제(절반 공개 DB 보호, 하루 기준 시간대 통일)는 그대로</li></ul>`,27)])])}const p=e(l,[["render",r]]);export{h as __pageData,p as default};
